{
  "name": "opencode-workaholic",
  "version": "0.4.0",
  "description": "Your OpenCode becomes a workaholic. Prevents AI from ending tasks prematurely.",
  "author": {
    "name": "Roderick Qiu",
    "email": "scrisqiu@hotmail.com",
    "url": "https://r-q.name"
  },
  "license": "MIT",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "opencode-workaholic": "./dist/cli.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/RoderickQiu/opencode-workaholic.git"
  },
  "bugs": {
    "url": "https://github.com/RoderickQiu/opencode-workaholic/issues"
  },
  "keywords": ["opencode", "plugin", "workaholic", "ai", "productivity", "timer", "focus", "deep-work", "task-duration", "task-management", "enforcement", "concentration", "agent", "automation"],
  "homepage": "https://workaholic.r-q.name/",
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "files": [
    "dist",
    "scripts"
  ],
  "scripts": {
    "build": "bun build ./src/index.ts --outdir dist --target bun && bun build ./src/cli.ts --outdir dist --target bun && cp -r src/command dist/ && cp -r scripts dist/"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.0.85",
    "zod": "^3.24.0"
  },
  "devDependencies": {
    "@eslint/js": "^9.39.1",
    "@types/node": "^20.11.5",
    "@typescript-eslint/eslint-plugin": "8.47.0",
    "@typescript-eslint/parser": "8.47.0",
    "bun-types": "latest",
    "eslint": "^9.39.1",
    "eslint-config-prettier": "10.1.8",
    "eslint-plugin-prettier": "^5.1.3",
    "prettier": "^3.2.4",
    "typescript-eslint": "^8.47.0",
    "vitest": "^3.2.4"
  }
}
